/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: albumInput, trackInput, album, track, entry, artists, refused, output, withKey
 *   Constants: slotA, slotB, manifest, baseline, blank, context
 * Tests
 *   - accepts every v2 field, normalizes complete ordered Artist entries and keeps no identity
 *   - refuses identities, identifiers (evidence included), unknown keys and fields
 *   - refuses Artist entries that break the Draft v2 entry rules
 *   - refuses over-limit counts, duplicate paths, misplaced fields, mixed value slots and null values
 *   - refuses folder evidence without a folder and review numbers without a filename
 *   - the transport sends the strict v2 schema, the v2 prompt and the labelled lookup context in one call
 *   - a 5xx or a thrown fetch is an unknown outcome after exactly one call each, and invalid output is never retried
 * @end-catalog */

/**
 * Luna json_schema v2 (adminImportProvider.ts): what validateLunaSuggestions accepts, the all-or-nothing refusals that make a
 * response providerInvalidResponse, and the fixed transport with the v2 schema, prompt and labelled lookup context.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { ImportProviderError, OpenAiImportAnalysisProvider, validateLunaSuggestions, type AnalysisInput, type LunaLookupContext } from '../../src/administration/import/adminImportProvider';

const slotA = '00000001-0000-4000-8000-00000000000a', slotB = '00000001-0000-4000-8000-00000000000b';
const manifest = { rootLabel: 'Lorem Ensemble - Ipsum', files: [{ slotId: slotA, filename: 'CD2/2-03 Lorem.mp3', relativePath: 'CD2/2-03 Lorem.mp3', byteLength: 1 }, { slotId: slotB, filename: '04 Ipsum.mp3', relativePath: 'CD2/04 Ipsum.mp3', byteLength: 1 }] };
const baseline = { album: { title: '', artists: [], label: null, releaseDate: null }, tracks: [] };
const albumInput = (extra: Partial<AnalysisInput> = {}): AnalysisInput => ({ generation: 1, chunk: 0, manifest, baseline, slots: [], album: true, tags: [], lookupContext: null, ...extra });
const trackInput = (extra: Partial<AnalysisInput> = {}): AnalysisInput => ({ ...albumInput(), chunk: 1, album: false, slots: [slotA, slotB],
    baseline: { ...baseline, tracks: [slotA, slotB].map(slotId => ({ slotId, title: '', discNumber: null, trackNumber: null })) }, ...extra });
const blank = { text: null, number: null, date: null, artists: null };
const album = (field: string, value: Record<string, unknown>, extra: Record<string, unknown> = {}) => ({ scope: 'album', slotId: null, field, ...blank, ...value, source: 'folder', evidence: 'Folder name', ...extra });
const track = (field: string, value: Record<string, unknown>, extra: Record<string, unknown> = {}) => ({ scope: 'track', slotId: slotA, field, ...blank, ...value, source: 'filename', evidence: 'Filename', ...extra });
const entry = (name: string, role = 'primary', joinPhrase: string | null = null) => ({ name, role, joinPhrase });
const artists = (...entries: unknown[]) => album('artists', { artists: entries });
const refused = (suggestions: unknown[], input = albumInput()) =>
    assert.throws(() => validateLunaSuggestions({ suggestions }, input), (error: ImportProviderError) => error instanceof ImportProviderError && error.issue === 'providerInvalidResponse', JSON.stringify(suggestions).slice(0, 200));

test('accepts every v2 field, normalizes complete ordered Artist entries and keeps no identity', () => {
    const date = { year: 2024, month: 3, day: null };
    const albumValues = validateLunaSuggestions({ suggestions: [album('title', { text: ' Ipsum ' }), artists(entry('Lorem Ensemble', 'primary', ' & '), entry('Ame\u0301lie Trio', 'primary', ' feat. '), entry('  Sit  ', 'featured')),
        album('label', { text: 'Amet Records' }), album('releaseDate', { date })] }, albumInput());
    assert.deepEqual(albumValues.map(({ field, value }) => [field, value]), [['title', 'Ipsum'],
        ['artists', [{ name: 'Lorem Ensemble', role: 'primary', joinPhrase: ' & ' }, { name: 'Am\u00e9lie Trio', role: 'primary', joinPhrase: ' feat. ' }, { name: 'Sit', role: 'featured', joinPhrase: null }]],
        ['label', 'Amet Records'], ['releaseDate', date]]);
    assert.ok(albumValues.every(value => !('baseline' in value) && !('musicBrainzId' in value)));
    const trackValues = validateLunaSuggestions({ suggestions: [track('title', { text: 'Lorem' }), track('discNumber', { number: 2 }), track('trackNumber', { number: 3 }), track('discNumber', { number: 999 }, { slotId: slotB }), track('discNumber', { number: 1 }, { slotId: slotB, field: 'trackNumber' })] }, trackInput());
    assert.deepEqual(trackValues.map(({ slotId, field, value }) => [slotId, field, value]), [[slotA, 'title', 'Lorem'], [slotA, 'discNumber', 2], [slotA, 'trackNumber', 3], [slotB, 'discNumber', 999], [slotB, 'trackNumber', 1]]);
    // A catalog review takes Disc and Track Numbers only from an actual filename; Artist entries and the label may come from context.
    const review = trackInput({ purpose: 'catalogReview', manifest: { rootLabel: '', files: [{ slotId: slotA, filename: '2-03 Lorem.mp3', relativePath: '', byteLength: null }, { slotId: slotB, filename: '', relativePath: '', byteLength: null }] } });
    assert.equal(validateLunaSuggestions({ suggestions: [track('discNumber', { number: 2 }), track('trackNumber', { number: 3 })] }, review).length, 2);
    assert.equal(validateLunaSuggestions({ suggestions: [artists(entry('Lorem')), album('label', { text: 'Amet' })].map(item => ({ ...item, source: 'context' })) }, albumInput({ purpose: 'catalogReview', manifest: review.manifest })).length, 2);
});

test('refuses identities, identifiers (evidence included), unknown keys and fields', () => {
    for (const key of ['musicBrainzId', 'key', 'id', 'candidateId', 'decision']) {
        refused([{ ...album('title', { text: 'Ipsum' }), [key]: null }]);
        refused([artists({ ...entry('Lorem'), [key]: key === 'musicBrainzId' ? '0383dadf-2a4e-4d10-a46a-e9e041da8eb3' : 'x' })]);
    }
    for (const field of ['artistName', 'visibility', 'musicBrainzId']) refused([album(field, { text: 'Lorem' })]);
    const { artists: _artists, ...missing } = album('title', { text: 'Ipsum' }); refused([missing]);
    for (const text of ['0383dadf-2a4e-4d10-a46a-e9e041da8eb3', 'Release 0383DADF-2A4E-4D10-A46A-E9E041DA8EB3', '64b5f0c2a1b2c3d4e5f60718']) {
        refused([album('title', { text })]); refused([album('label', { text })]); refused([artists(entry(text))]);
    }
    refused([album('title', { text: 'Ipsum' }, { candidateId: '64b5f0c2a1b2c3d4e5f60718' })]);
    // Evidence is shown to administrators as Luna's justification, so it may not carry an identifier either.
    for (const evidence of ['mbid 0383dadf-2a4e-4d10-a46a-e9e041da8eb3', 'catalog 64b5f0c2a1b2c3d4e5f60718']) refused([album('title', { text: 'Ipsum' }, { evidence })]);
    refused([{ suggestions: [] }].map(() => album('title', { text: 'Ipsum' }, { source: 'lookup' })));
    assert.throws(() => validateLunaSuggestions({ suggestions: [], extra: true }, albumInput()), ImportProviderError);
});

test('refuses Artist entries that break the Draft v2 entry rules', () => {
    refused([artists(entry('Sit', 'featured'), entry('Lorem'))]);
    refused([artists(entry('Lorem'), entry('LOREM'))]);
    for (const phrase of ['   ', 'x'.repeat(17)]) refused([artists(entry('Lorem', 'primary', phrase), entry('Ipsum'))]);
    for (const name of ['Lorem\u200bIpsum', 'Lorem\u0007', '', ' ']) refused([artists(entry(name))]);
    refused([artists(entry('Lorem', 'composer'))]);
    refused([artists(...Array.from({ length: 21 }, (_, index) => entry(`Lorem ${index}`)))]);
    assert.equal(validateLunaSuggestions({ suggestions: [artists(...Array.from({ length: 20 }, (_, index) => entry(`Lorem ${index}`)))] }, albumInput())[0].value.length, 20);
    refused([artists()]);
    refused([album('artists', { artists: null, text: 'Lorem' })]);
});

test('refuses over-limit counts, duplicate paths, misplaced fields, mixed value slots and null values', () => {
    const four = [album('title', { text: 'Ipsum' }), artists(entry('Lorem')), album('label', { text: 'Amet' }), album('releaseDate', { date: { year: 2024, month: null, day: null } })];
    assert.equal(validateLunaSuggestions({ suggestions: four }, albumInput()).length, 4);
    refused([...four, album('title', { text: 'Again' })]);
    const seven = [...['title', 'discNumber', 'trackNumber'].flatMap(field => [slotA, slotB].map(slotId => track(field, field === 'title' ? { text: 'Lorem' } : { number: 1 }, { slotId }))), track('title', { text: 'Extra' })];
    refused(seven, trackInput());
    refused([album('title', { text: 'Ipsum' }), album('title', { text: 'Dolor' })]);
    for (const field of ['label', 'artists']) refused([track(field, field === 'label' ? { text: 'Amet' } : { artists: [entry('Lorem')] })], trackInput());
    for (const field of ['discNumber', 'trackNumber']) refused([album(field, { number: 1 })]);
    refused([track('title', { text: 'Lorem' })]);
    refused([album('title', { text: 'Ipsum' })], trackInput());
    refused([track('title', { text: 'Lorem' }, { slotId: '00000001-0000-4000-8000-0000000000ff' })], trackInput());
    refused([album('title', { text: 'Ipsum', number: 1 })]);
    refused([album('label', { text: 'Amet', artists: [entry('Amet')] })]);
    for (const value of [album('label', {}), album('releaseDate', {}), album('title', {}), album('title', { text: '' })]) refused([value]);
    for (const value of [track('discNumber', {}), track('trackNumber', {}), track('discNumber', { number: 0 }), track('discNumber', { number: 1000 }), track('trackNumber', { number: 10000 }), track('discNumber', { number: 1.5 })]) refused([value], trackInput());
});

test('refuses folder evidence without a folder and review numbers without a filename', () => {
    const folderless = albumInput({ manifest: { rootLabel: '', files: [{ ...manifest.files[1], relativePath: '04 Ipsum.mp3' }] } });
    refused([album('title', { text: 'Ipsum' })], folderless);
    assert.equal(validateLunaSuggestions({ suggestions: [album('title', { text: 'Ipsum' }, { source: 'filename' })] }, folderless).length, 1);
    const review = trackInput({ purpose: 'catalogReview', manifest: { rootLabel: '', files: [{ slotId: slotA, filename: '', relativePath: '', byteLength: null }, { slotId: slotB, filename: '2-04 Ipsum.mp3', relativePath: '', byteLength: null }] } });
    refused([track('discNumber', { number: 2 }, { source: 'context', slotId: slotB })], review);
    refused([track('trackNumber', { number: 4 }, { source: 'context', slotId: slotB })], review);
    refused([track('discNumber', { number: 2 })], review);
    refused([track('title', { text: 'Lorem' }, { source: 'folder', slotId: slotB })], review);
});

const output = (text: string) => ({ status: 'completed', output: [{ type: 'message', content: [{ type: 'output_text', text }] }] });
const context: LunaLookupContext = { source: 'musicbrainz', kind: 'appliedRelease', trust: 'untrusted', truncated: false,
    release: { title: 'Ipsum', artistCredit: [{ name: 'Lorem Ensemble', joinPhrase: '' }], labels: ['Amet Records'], date: null, firstReleaseDate: null, media: [{ position: 2, format: 'CD', tracks: [{ position: 3, number: '3', title: 'Lorem', lengthMs: 1000 }] }] } };
const withKey = async (work: () => Promise<void>) => {
    const previous = process.env.OPENAI_API_KEY; process.env.OPENAI_API_KEY = 'synthetic-key';
    try { await work(); } finally { if (previous === undefined) delete process.env.OPENAI_API_KEY; else process.env.OPENAI_API_KEY = previous; }
};

test('the transport sends the strict v2 schema, the v2 prompt and the labelled lookup context in one call', () => withKey(async () => {
    let calls = 0; const bodies: Record<string, any>[] = [];
    const provider = new OpenAiImportAnalysisProvider(async (_url, init) => {
        calls++; bodies.push(JSON.parse(init!.body as string));
        return new Response(JSON.stringify(output(JSON.stringify({ suggestions: [album('label', { text: 'Amet Records' }, { source: 'context', evidence: 'lookupContext label' })] }))));
    });
    assert.deepEqual(await provider.analyze(albumInput({ lookupContext: context })), [{ scope: 'album', slotId: null, field: 'label', value: 'Amet Records', source: 'context', evidence: 'lookupContext label' }]);
    assert.equal(calls, 1);
    const [body] = bodies, format = body.text.format;
    assert.deepEqual([body.store, body.tools, body.max_output_tokens, format.type, format.name, format.strict], [false, undefined, 4000, 'json_schema', 'album_import_suggestions_v2', true]);
    const item = format.schema.properties.suggestions.items;
    assert.deepEqual(item.required, ['scope', 'slotId', 'field', 'text', 'number', 'date', 'artists', 'source', 'evidence']);
    assert.deepEqual(item.properties.field.enum, ['title', 'artists', 'label', 'releaseDate', 'discNumber', 'trackNumber']);
    assert.deepEqual([item.additionalProperties, item.properties.artists.items.additionalProperties, item.properties.artists.items.required], [false, false, ['name', 'role', 'joinPhrase']]);
    assert.match(body.instructions, /Never output identifiers of any kind \(MusicBrainz, catalog, barcode, ISRC or other IDs\) and never choose, match or describe existing catalog records/);
    assert.match(body.instructions, /Disc numbers require disc evidence such as a disc folder or filename part \(CD2, Disc 2, a 2-03 prefix\), a disc tag, or the same track's disc position in lookupContext/);
    const sent = JSON.parse(body.input);
    assert.deepEqual([sent.lookupContext.source, sent.lookupContext.kind, sent.lookupContext.trust], ['musicbrainz', 'appliedRelease', 'untrusted']);
    assert.deepEqual(sent.lookupContext.release, context.release);
}));

test('a 5xx or a thrown fetch is an unknown outcome after exactly one call each, and invalid output is never retried', () => withKey(async () => {
    let calls = 0;
    await assert.rejects(new OpenAiImportAnalysisProvider(async () => { calls++; return new Response('private', { status: 503 }); }).analyze(albumInput()), (error: ImportProviderError) => error.issue === 'providerOutcomeUnknown');
    assert.equal(calls, 1);
    await assert.rejects(new OpenAiImportAnalysisProvider(async () => { calls++; throw new Error('private'); }).analyze(albumInput()), (error: ImportProviderError) => error.issue === 'providerOutcomeUnknown' && !error.message.includes('private'));
    assert.equal(calls, 2);
    await assert.rejects(new OpenAiImportAnalysisProvider(async () => { calls++; return new Response(JSON.stringify(output(JSON.stringify({ suggestions: [album('artistName', { text: 'Lorem' })] })))); }).analyze(albumInput()),
        (error: ImportProviderError) => error.issue === 'providerInvalidResponse');
    assert.equal(calls, 3);
}));
